      ['Герметично ли безрамное остекление?','Холодные безрамные системы защищают от прямого ветра и осадков, но не равны герметичному тёплому фасаду.'],
      ['Можно ли сделать систему без порога?','Для отдельных верхнеподвесных систем — да, если верхнее основание выдерживает нагрузку.']
