      { id:'voda', title:'Уклон и водоотведение', paragraphs:['Вода не должна застаиваться на стекле или в стыках. Уклон, желоба, прижимные планки, герметики и примыкания проектируют до изготовления каркаса.'] },
      { id:'sonce', title:'Солнцезащита и перегрев', paragraphs:['Прозрачная крыша может существенно нагревать пространство. Для зимнего сада или террасы оценивают солнцезащитные свойства стекла, ориентацию, внешнее затенение и вентиляцию.'] },
      { id:'servis', title:'Доступ для очистки и сервиса', paragraphs:['Ещё на этапе проекта нужно предусмотреть безопасный способ мойки, очистки водостоков и осмотра герметизации. Ходить по стеклу без специально предусмотренного решения нельзя.'] }
