      { id:'dokumenty', title:'Что запросить у производителя', paragraphs:['Уточните стандарт испытания, маркировку, прослеживаемость партии и документы, подтверждающие прохождение цикла. Это особенно важно для проектных и коммерческих объектов.'] }
