          'В безрамном остеклении террас тонированное стекло Space Glass предлагает ещё и для того, чтобы уменьшить слепящее солнце. В гардеробных тонированные раздвижные полотна выглядят эффектно, хотя содержимое шкафов сквозь них частично видно — если его нужно скрыть полностью, лучше матовое.',
