          'В душевых матовое и рифлёное стекло закрывают зону душа, а графит и бронза тонируют её. В стеклянных ограждениях и козырьках ассортимент уже и зависит от системы: там чаще выбирают прозрачное, экстрапрозрачное, матовое или тонированное стекло.',
