    title: 'Отверстия и вырезы в стекле: что учесть до закалки',
    description: 'Почему отверстия и вырезы в закалённом стекле делают только до закалки: какие отверстия нужны дверям, ограждениям и зеркалам и что зафиксировать в чертеже.',
    intro: 'Закалённое стекло нельзя просверлить или подрезать после изготовления. Поэтому каждое отверстие под петлю, ручку или держатель и каждый вырез под розетку или ступеньку нужно определить заранее. Объясняем, какие отверстия бывают в разных конструкциях и как не ошибиться до запуска стекла в производство.',
