          'Для пятиугольных кабин есть готовые размеры под стандартные поддоны 900×900 и 1000×1000 мм; для другой геометрии кабину изготавливают индивидуально.',
          'Основанием может быть готовый поддон или пол с уклоном к трапу и гидроизоляцией. Поддон задаёт точную форму кабины и упрощает защиту от воды; трап даёт ровный пол без борта, но уклон нужно спланировать до замера стекла.',
