          'Тип открывания тоже важен. Распашная дверь с правильным притвором плотнее раздвижной: обычная навесная раздвижная система не обеспечивает такой же плотности, поэтому для комнат, где важна тишина, раздвижная дверь без специального уплотнения — компромисс.',
