          'Собранный пакет полотен занимает часть проёма, и это стоит учесть заранее: у места парковки не должно быть мебели, выключателей или дверей, которые будут мешать. Если проём нужно освободить почти полностью, рассматривают трансформируемые системы, где полотна складываются или поворачиваются и откатываются в сторону.',
