    intro: 'Фигурное зеркало должно точно совпасть со стеной, нишей или мебелью — иначе ошибку видно сразу. Объясняем, когда достаточно эскиза, а когда нужен шаблон на объекте, что фиксируют в чертеже и почему крепление продумывают вместе с формой.',
