    intro: 'Ограждение террасы должно защищать от перепада высоты и ветра, но не закрывать вид. Разбираем, чем оно отличается от остекления террасы, что меняет открытое расположение, как крепить стекло к бетону и деревянному настилу, что делать с водой и как ухаживать за стеклом снаружи.',
