          'Фурнитуру из нержавейки периодически протирают, особенно у моря и бассейна. В системах Space Glass для улицы применяют нержавейку AISI 316, которая лучше сопротивляется соли и влаге.',
          'Зимой лёд и снег не счищают со стекла металлическими скребками: царапины и удары по кромке для стекла опаснее, чем сам мороз.',
