          'в консольных системах стекло держит зажимной профиль или рама только на стене, без тяг и опор, поэтому стена должна быть особенно прочной;',
          'рама, алюминиевая или стальная, делает козырёк жёстче и позволяет большие площади, несколько полотен стекла и встроенный жёлоб.',
