          'От роли стекла зависит, насколько сложными будут расчёт и изготовление. Чем больше нагрузки стекло берёт на себя, тем точнее должны быть опоры, отверстия и монтаж.',
          'Стеклянные ступени часто сочетают со стеклянным ограждением, но это две разные конструкции с отдельными требованиями: ступени несут вес, ограждение защищает от падения.',
