          'Для других конструкций деление зависит от системы: в перегородках и ограждениях конструкция и так состоит из отдельных полотен, поэтому их размеры можно согласовать с возможностями заноса. Если же нужно именно одно большое полотно, способ доставки и подъёма обсуждают отдельно до заказа.',
